package com.example.hiringsys.service; import com.example.hiringsys.entity.Grupo; import com.example.hiringsys.enums.EstadoGrupo; import com.example.hiringsys.exception.*; import com.example.hiringsys.repository.GrupoRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service public class GrupoService { private final GrupoRepository repository; public GrupoService(GrupoRepository r){repository=r;} @Transactional(readOnly=true) public List<Grupo> listarTodos(){return repository.findAll();} @Transactional(readOnly=true) public Grupo buscarPorId(Long id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Grupo não encontrado: "+id));} @Transactional(readOnly=true) public List<Grupo> buscarPorNome(String n){return repository.findByNomeContainingIgnoreCase(n);} @Transactional(readOnly=true) public List<Grupo> buscarPorEstado(EstadoGrupo e){return repository.findByEstado(e);} @Transactional public Grupo salvar(Grupo g){g.setId(null);validar(g,null);return repository.save(g);} @Transactional public Grupo atualizar(Long id,Grupo d){Grupo g=buscarPorId(id);validar(d,id);g.setNome(d.getNome());g.setArea(d.getArea());g.setEstado(d.getEstado());g.setDisponiveis(d.getDisponiveis());g.setCargo(d.getCargo());return repository.save(g);} @Transactional public void excluir(Long id){repository.delete(buscarPorId(id));} private void validar(Grupo g,Long id){if(g.getDisponiveis()!=null&&g.getDisponiveis()<0)throw new BusinessRuleException("Vagas disponíveis não podem ser negativas");boolean x=id==null?repository.existsByNomeIgnoreCase(g.getNome()):repository.existsByNomeIgnoreCaseAndIdNot(g.getNome(),id);if(x)throw new BusinessRuleException("Grupo já cadastrado: "+g.getNome());} }
